    '$m = \\frac{2}{9}$ and $n = \\frac{4}{99}$. Left-hand side: $m^2 = (\\frac{2}{9})^2 = \\frac{4}{81}$. Right-hand side: $n(m + 1) = \\frac{4}{99}(\\frac{2}{9} + 1) = \\frac{4}{99} \\times \\frac{11}{9} = \\frac{4}{81}$. Hence $m^2 = n(m + 1)$.',
