    'Fractions always convert into either terminating decimals or non-terminating repeating decimals (rational numbers), whereas square roots of non-perfect squares ($\\sqrt{2}, \\sqrt{3}, \\sqrt{5}, \\dots$) produce non-terminating, non-repeating decimals (irrational numbers).',
