    '(a) $m = 3, (0, -12)$, (b) $m = \\frac{7}{2}, (0, \\frac{3}{2})$, (c) $m = -\\frac{a}{b}, (0, -\\frac{c}{b})$, (d) $m = -\\frac{b}{a}, (0, b)$.',
