    'Slope of $x + 4y - 1 = 0$ is $m = -\\frac{1}{4}$. Line through $(4, -3)$ is $y - (-3) = -\\frac{1}{4}(x - 4) \\implies 4y + 12 = -x + 4 \\implies x + 4y + 8 = 0$.',
